mapper.select:
select id, subscription_code, subscription_name, frequency, channel, target_type, recipients, enabled, last_dispatch_at, created_at, updated_at from risk_alert_subscription
where subscription_code like concat('%', #{keyword}, '%') or subscription_name like concat('%', #{keyword}, '%') or ifnull(recipients, '') like concat('%', #{keyword}, '%')
order by id desc limit #{limit} offset #{offset}

mapper.update:
update risk_alert_subscription
subscription_code = #{body.subscription_code}, subscription_name = #{body.subscription_name}, frequency = #{body.frequency}, channel = #{body.channel}, target_type = #{body.target_type}, recipients = #{body.recipients}, enabled = #{body.enabled},
where id = #{id}

update risk_alert_subscription
set last_dispatch_at = #{lastDispatchAt}
where id = #{id}
